  const body = page.locator('body');
  const bodyColor = await body.evaluate((el) => {
    const style = getComputedStyle(el);
    return { r: parseInt(style.backgroundColor.split(',')[0].replace(/\D/g, '')), g: parseInt(style.backgroundColor.split(',')[1]), b: parseInt(style.backgroundColor.split(',')[2]) };
  });
  expect(bodyColor.r > 200 && bodyColor.g > 200 && bodyColor.b > 200).toBeTruthy();

  const formBox = await c.form.boundingBox();
  expect(formBox).not.toBeNull();
  const formBg = await c.form.evaluate((el) => {
    let target = el;
    while (target) {
      const bg = getComputedStyle(target).backgroundColor;
      if (bg && bg !== 'rgba(0, 0, 0, 0)' && bg !== 'transparent') {
        const parts = bg.match(/\d+/g);
        if (parts) {
          return { r: parseInt(parts[0]), g: parseInt(parts[1]), b: parseInt(parts[2]) };
        }
      }
      target = target.parentElement;
    }
    return null;
  });
  if (formBg) {
    expect(formBg.r > 200 && formBg.g > 200 && formBg.b > 200).toBeTruthy();
  }

  const submitColor = await c.submit.evaluate((el) => {
    const style = getComputedStyle(el);
    return { r: parseInt(style.backgroundColor.split(',')[0].replace(/\D/g, '')), g: parseInt(style.backgroundColor.split(',')[1]), b: parseInt(style.backgroundColor.split(',')[2]) };
  });
  expect(submitColor.r > 150 && submitColor.g < 100 && submitColor.b < 100).toBeTruthy();

  await page.setViewportSize({ width: 1200, height: 800 });
  const formWidth = await c.form.evaluate((el) => el.offsetWidth);
  expect(formWidth).toBeLessThan(1100);

  await page.setViewportSize({ width: 375, height: 667 });
  await expect(page.locator('html')).not.toHaveCSS('overflow-x', /scroll/);
  const mobileFormWidth = await c.form.evaluate((el) => el.offsetWidth);
  expect(mobileFormWidth).toBeLessThanOrEqual(375);

  await c.username.focus();
  await expect(c.username).toBeFocused();
  const focusOutline = await c.username.evaluate((el) => {
    const style = getComputedStyle(el, ':focus');
    return style.outlineWidth !== '0px' || style.boxShadow !== 'none';
  });
  expect(focusOutline).toBeTruthy();
});
"}

